// Pure helpers for the generation form (no DOM), shared by app.js and the Node tests.

// The fields of GenerationCreate, in form order. generated_content is deliberately absent:
// the browser never sends content, it is always (re)generated by the AI provider.
export const FORM_FIELDS = [
  "content_type",
  "customer",
  "company",
  "industry",
  "product_or_service",
  "customer_email",
  "customer_needs",
  "price",
  "discount_percent",
  "salesperson",
  "salesperson_company",
  "language",
  "tone",
];

// Numeric inputs. The browser never calculates with them: it only converts the Spanish decimal
// comma for the API, which validates and calculates with Decimal.
export const DECIMAL_FIELDS = ["price", "discount_percent"];

/** "49,99" -> "49.99". Anything else is sent as typed, for the API to validate. */
export function normalizeDecimal(value) {
  const text = String(value ?? "").trim();
  return /^\d+,\d+$/.test(text) ? text.replace(",", ".") : text;
}

/** Form values ready for POST /generate or PUT /generations/{id}. */
export function toApiPayload(values) {
  const payload = { ...values };
  for (const field of DECIMAL_FIELDS) {
    if (field in payload) payload[field] = normalizeDecimal(payload[field]);
  }
  return payload;
}

/** "179.00" -> "179", "49.99" -> "49,99", "12.50" -> "12,5" (how a stored number is shown in an input). */
export function decimalForInput(value) {
  if (value === null || value === undefined || value === "") return "";
  let text = String(value);
  if (text.includes(".")) text = text.replace(/0+$/, "").replace(/\.$/, "");
  return text.replace(".", ",");
}

/** The form values to load when editing a stored generation. */
export function formValuesFrom(generation) {
  // Optional fields of older generations come back as null: shown as empty inputs.
  return Object.fromEntries(
    FORM_FIELDS.map((field) => [
      field,
      DECIMAL_FIELDS.includes(field) ? decimalForInput(generation[field]) : (generation[field] ?? ""),
    ]),
  );
}

// Subject of the share-by-email button (fixed corporate subject).
export const SHARE_EMAIL_SUBJECT = "Propuesta Comercial - Kodexia";

/**
 * Links to share a generated text: the default mail client (mailto:) addressed to the customer's
 * email when there is one, and WhatsApp (wa.me without a number: the user picks the chat).
 */
export function shareLinks(text, customerEmail = "") {
  const body = encodeURIComponent(text);
  // The email was validated by the API; encodeURI keeps the @ readable for every mail client.
  const to = customerEmail ? encodeURI(customerEmail.trim()) : "";
  return {
    email: `mailto:${to}?subject=${encodeURIComponent(SHARE_EMAIL_SUBJECT)}&body=${body}`,
    whatsapp: `https://wa.me/?text=${body}`,
  };
}

/** Short label identifying a generation in the edit banner and delete confirmation. */
export function describeGeneration(generation, contentTypeLabels = {}) {
  const type = contentTypeLabels[generation.content_type] ?? generation.content_type;
  return `#${generation.id} · ${type} · ${generation.customer} (${generation.company})`;
}
